#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string filename, word;
    int count = 0;

    // Get the filename and word to search for from user input
    cout << "Enter the filename: ";
    cin >> filename;

    cout << "Enter the word to search for: ";
    cin >> word;

    // Open the file for reading
    ifstream file(filename);

    if (!file) {
        cerr << "Error opening file: " << filename << endl;
        return 1;
    }

    // Read the file line by line and count occurrences of the word
    string line;
    while (getline(file, line)) {
        transform(line.begin(), line.end(), line.begin(), ::tolower); // Convert to lowercase for case-insensitive search
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            pos++; // Increment position to avoid finding the same word again
            count++;
        }
    }

    // Close the file
    file.close();

    // Display the count
    cout << "The word \"" << word << "\" appears " << count << " times in " << filename << endl;

    return 0;
}
```

Note that this program assumes that the text file contains only ASCII characters (i.e., no Unicode characters). If your file contains Unicode characters, you may need to use a library like ICU (International Components for Unicode) to handle Unicode text. Also, this program performs a case-insensitive search by converting both the line and the word to lowercase before searching. If you want a case-sensitive search, remove the `transform` line.
